import math
import numpy as np
from scipy.special import wofz

def _bell_idle(rho, duration):
    damping = 1 - math.exp(-duration / 6.8e-05)
    decay = math.exp(-duration / 8.9e-05)
    data = rho.reshape(-1, 2, 2, 2, 2)
    data[:, 0, :, 0, :] += damping * data[:, 1, :, 1, :]
    data[:, 1, :, 1, :] *= 1 - damping
    data[:, 0, :, 1, :] *= decay
    data[:, 1, :, 0, :] *= decay
    data[:, :, 0, :, 0] += damping * data[:, :, 1, :, 1]
    data[:, :, 1, :, 1] *= 1 - damping
    data[:, :, 0, :, 1] *= decay
    data[:, :, 1, :, 0] *= decay

def _bell_depolarize(rho, qubit, error):
    data = rho.reshape(-1, 2, 2, 2, 2)
    factor = 1 - 4 * error / 3
    if qubit == 0:
        trace = data[:, 0, :, 0, :] + data[:, 1, :, 1, :]
        data *= factor[:, None, None, None, None]
        part = (1 - factor[:, None, None]) * trace / 2
        data[:, 0, :, 0, :] += part
        data[:, 1, :, 1, :] += part
    else:
        trace = data[:, :, 0, :, 0] + data[:, :, 1, :, 1]
        data *= factor[:, None, None, None, None]
        part = (1 - factor[:, None, None]) * trace / 2
        data[:, :, 0, :, 0] += part
        data[:, :, 1, :, 1] += part

def _bell_readout(probabilities, pairs, zero, one):
    data = probabilities.reshape(-1, 2, 2).copy()
    for q in (0, 1):
        e0 = np.array([float(zero[pair[q]][0]) for pair in pairs])
        e1 = np.array([float(one[pair[q]][0]) for pair in pairs])
        if q == 0:
            a, b = (data[:, 0, :].copy(), data[:, 1, :].copy())
            data[:, 0, :] = (1 - e0[:, None]) * a + e1[:, None] * b
            data[:, 1, :] = e0[:, None] * a + (1 - e1[:, None]) * b
        else:
            a, b = (data[:, :, 0].copy(), data[:, :, 1].copy())
            data[:, :, 0] = (1 - e0[:, None]) * a + e1[:, None] * b
            data[:, :, 1] = e0[:, None] * a + (1 - e1[:, None]) * b
    return data.reshape(-1, 4)

def _bell_probabilities(calibration, alternate=False):
    cz, sq, zero, one = calibration
    active = set(sq) & set(zero) & set(one)
    pairs, errors = ([], [])
    for pair, error in cz.items():
        a, b = tuple(pair)
        if a not in active or b not in active or a == b:
            continue
        for root, child in ((a, b), (b, a)):
            pairs.append((root, child))
            errors.append((float(sq[root][0]), float(sq[child][0]), float(error[0])))
    if not pairs:
        raise NotImplementedError('no calibrated pair')
    errors = np.array(errors)
    first = np.broadcast_to(np.eye(2) / 2, (len(pairs), 2, 2)).copy()
    second = first.copy()
    first[:, 0, 1] = first[:, 1, 0] = -(1 - 4 * errors[:, 0] / 3) / 2
    second[:, 0, 1] = second[:, 1, 0] = (1 - 4 * errors[:, 1] / 3) / 2
    rho = np.einsum('bij,bkl->bikjl', first, second).reshape(-1, 4, 4)
    _bell_idle(rho, 2.5e-08)
    sign = np.array([1, 1, 1, -1])
    rho *= sign[None, :, None] * sign[None, None, :]
    factor = (1 - 16 * errors[:, 2] / 15)[:, None, None]
    rho = factor * rho + (1 - factor) * np.eye(4)[None] / 4
    _bell_idle(rho, 4.2e-08)
    h = np.array([[1, 1], [1, -1]]) / math.sqrt(2)
    x = np.array([[0, 1], [1, 0]])
    gate = np.kron(np.eye(2), x @ h @ x) if alternate else np.kron(h, np.eye(2))
    rho = gate @ rho @ gate.T
    last = 1 if alternate else 0
    _bell_depolarize(rho, last, errors[:, last])
    _bell_idle(rho, 2.5e-08)
    pz = _bell_readout(np.diagonal(rho, axis1=1, axis2=2), pairs, zero, one)
    gate = np.kron(h, h)
    rho = gate @ rho @ gate.T
    _bell_depolarize(rho, 0, errors[:, 0])
    _bell_depolarize(rho, 1, errors[:, 1])
    _bell_idle(rho, 2.5e-08)
    px = _bell_readout(np.diagonal(rho, axis1=1, axis2=2), pairs, zero, one)
    return (pairs, pz, px)

def _bell_scores(pz, px, shots=10000, order=20):
    fraction = pz[:, 1] + pz[:, 2]
    delta = (pz[:, 1] - pz[:, 2]) / fraction
    count = shots * fraction
    mean_d = count * delta
    std_d = np.sqrt(count * (1 - delta * delta))
    zfactor = shots / (2 * count * count)
    mean1 = px[:, 0] - px[:, 3]
    mean2 = 1 - 2 * (px[:, 1] + px[:, 2])
    variance1 = (px[:, 0] + px[:, 3] - mean1 ** 2) / shots
    variance2 = (1 - mean2 ** 2) / shots
    covariance = mean1 * (1 - mean2) / shots
    nodes, weights = np.polynomial.hermite.hermgauss(order)
    mesh = np.stack(np.meshgrid(nodes, nodes), axis=-1).reshape(-1, 2) * math.sqrt(2)
    weights = np.outer(weights, weights).ravel() / math.pi
    l11 = np.sqrt(np.maximum(variance1, 1e-18))
    l21 = covariance / l11
    l22 = np.sqrt(np.maximum(variance2 - l21 * l21, 1e-18))
    samples1 = mean1[:, None] + l11[:, None] * mesh[:, 0]
    samples2 = mean2[:, None] + l21[:, None] * mesh[:, 0] + l22[:, None] * mesh[:, 1]
    x = samples1 ** 2 + (1 - samples2) ** 2
    gamma = np.sqrt(np.maximum(x, 1e-20) / zfactor[:, None])
    voigt = wofz((mean_d[:, None] + 1j * gamma) / (math.sqrt(2) * std_d[:, None])).real
    expected = math.sqrt(math.pi / 2) * voigt / (zfactor[:, None] * std_d[:, None] * gamma)
    return expected @ weights

import itertools
import math
import cirq
import numpy as np

def calibration_rate(value):
    try:
        return float(value[0])
    except (TypeError, IndexError):
        return float(value)

class BatchDensity:

    def __init__(self, n, batch):
        self.n = n
        self.batch = batch
        self.tensor = np.zeros((batch,) + (2,) * (2 * n), dtype=np.complex128)
        self.tensor[(slice(None),) + (0,) * (2 * n)] = 1

    def index(self, fixed):
        result = [slice(None)] * (2 * self.n + 1)
        for axis, value in fixed.items():
            result[axis + 1] = value
        return tuple(result)

    def unitary(self, q, matrix):
        temporary = np.moveaxis(np.tensordot(matrix, self.tensor, axes=([1], [q + 1])), 0, q + 1)
        self.tensor = np.moveaxis(np.tensordot(matrix.conj(), temporary, axes=([1], [self.n + q + 1])), 0, self.n + q + 1)

    def cz(self, a, b):
        for x, y in ((a, b), (self.n + a, self.n + b)):
            self.tensor[self.index({x: 1, y: 1})] *= -1

    def depolarize(self, qubits, errors):
        factor = 4 ** len(qubits) * np.asarray(errors) / (4 ** len(qubits) - 1)
        diagonal = [dict(zip([*qubits, *(self.n + q for q in qubits)], bits + bits)) for bits in itertools.product((0, 1), repeat=len(qubits))]
        reduced = sum((self.tensor[self.index(bits)] for bits in diagonal)) / 2 ** len(qubits)
        self.tensor *= (1 - factor).reshape((-1,) + (1,) * (2 * self.n))
        addition = factor.reshape((-1,) + (1,) * (2 * self.n - 2 * len(qubits))) * reduced
        for bits in diagonal:
            self.tensor[self.index(bits)] += addition

    def idle(self, duration):
        damping = 1 - math.exp(-duration / 6.8e-05)
        decay = math.exp(-duration / 8.9e-05)
        for q in range(self.n):
            self.tensor[self.index({q: 0, self.n + q: 0})] += damping * self.tensor[self.index({q: 1, self.n + q: 1})]
            self.tensor[self.index({q: 1, self.n + q: 1})] *= 1 - damping
            self.tensor[self.index({q: 0, self.n + q: 1})] *= decay
            self.tensor[self.index({q: 1, self.n + q: 0})] *= decay

    def probabilities(self):
        matrix = self.tensor.reshape(self.batch, 2 ** self.n, 2 ** self.n)
        return np.clip(np.diagonal(matrix, axis1=1, axis2=2).real, 0, None)

def apply_readout(probabilities, placements, zero, one):
    n = len(placements[0])
    data = probabilities.reshape((-1,) + (2,) * n).copy()
    for q in range(n):
        e0 = np.array([calibration_rate(zero[placement[q]]) for placement in placements])
        e1 = np.array([calibration_rate(one[placement[q]]) for placement in placements])
        index0, index1 = ([slice(None)] * (n + 1), [slice(None)] * (n + 1))
        index0[q + 1], index1[q + 1] = (0, 1)
        index0, index1 = (tuple(index0), tuple(index1))
        a, b = (data[index0].copy(), data[index1].copy())
        e0, e1 = (e0.reshape((-1,) + (1,) * (n - 1)), e1.reshape((-1,) + (1,) * (n - 1)))
        data[index0] = (1 - e0) * a + e1 * b
        data[index1] = e0 * a + (1 - e1) * b
    result = data.reshape(-1, 2 ** n)
    return result / result.sum(axis=1)[:, None]

def batch_probabilities(circuit, logical, placements, calibration):
    cz, sq, zero, one = calibration
    n = len(logical)
    index = {q: i for i, q in enumerate(logical)}
    errors = np.array([[calibration_rate(sq[q]) for q in placement] for placement in placements])
    pair_errors = {}
    for edge, value in cz.items():
        a, b = tuple(edge)
        pair_errors[a, b] = pair_errors[b, a] = calibration_rate(value)
    density = BatchDensity(n, len(placements))
    for moment in circuit:
        duration = 4.2e-08 if any((len(op.qubits) == 2 for op in moment)) else 2.5e-08
        for op in moment:
            if op.gate == cirq.CZ:
                density.cz(*(index[q] for q in op.qubits))
            else:
                density.unitary(index[op.qubits[0]], cirq.unitary(op))
        for op in moment:
            qs = [index[q] for q in op.qubits]
            if len(qs) == 2:
                rates = np.array([pair_errors[placement[qs[0]], placement[qs[1]]] for placement in placements])
            else:
                rates = errors[:, qs[0]]
            density.depolarize(qs, rates)
        density.idle(duration)
    pz = apply_readout(density.probabilities(), placements, zero, one)
    h = cirq.unitary(cirq.H)
    for q in range(n):
        density.unitary(q, h)
    for q in range(n):
        density.depolarize([q], errors[:, q])
    density.idle(2.5e-08)
    px = apply_readout(density.probabilities(), placements, zero, one)
    return (pz, px)

def batch_probabilities_detuned(circuit, logical, placements, calibration, detuning_khz=7.5):
    cz, sq, zero, one = calibration
    n, batch = (len(logical), len(placements))
    index = {q: i for i, q in enumerate(logical)}
    components = n + 2
    errors = np.array([[calibration_rate(sq[q]) for q in placement] for placement in placements])
    errors = np.tile(errors, (components, 1))
    pair_errors = {}
    for edge, value in cz.items():
        a, b = tuple(edge)
        pair_errors[a, b] = pair_errors[b, a] = calibration_rate(value)
    density = BatchDensity(n, components * batch)
    density.tensor[batch:] = 0

    def phase(duration):
        angle = 2 * math.pi * detuning_khz * 1000.0 * duration
        data = density.tensor.reshape((components, batch) + (2,) * (2 * n))
        for q in range(n):
            for row, col, sign in ((0, 1, -1), (1, 0, 1)):
                position = [slice(None)] * (2 * n + 2)
                position[q + 2], position[n + q + 2] = (row, col)
                position[0] = 0
                original = data[tuple(position)]
                position[0] = q + 1
                first = tuple(position)
                position[0] = components - 1
                second = tuple(position)
                data[second] += sign * 2j * angle * data[first] - angle * angle * original
                data[first] += sign * 1j * angle * original

    def measured():
        matrix = density.tensor.reshape(components, batch, 2 ** n, 2 ** n)
        diagonal = np.diagonal(matrix[0] + 0.5 * matrix[-1], axis1=1, axis2=2).real
        return apply_readout(np.maximum(diagonal, 0), placements, zero, one)
    for moment in circuit:
        duration = 4.2e-08 if any((len(op.qubits) == 2 for op in moment)) else 2.5e-08
        for op in moment:
            if op.gate == cirq.CZ:
                density.cz(*(index[q] for q in op.qubits))
            else:
                density.unitary(index[op.qubits[0]], cirq.unitary(op))
        for op in moment:
            qs = [index[q] for q in op.qubits]
            if len(qs) == 2:
                rates = np.tile([pair_errors[placement[qs[0]], placement[qs[1]]] for placement in placements], components)
            else:
                rates = errors[:, qs[0]]
            density.depolarize(qs, rates)
        density.idle(duration)
        phase(duration)
    pz = measured()
    for q in range(n):
        density.unitary(q, cirq.unitary(cirq.H))
        density.depolarize([q], errors[:, q])
    density.idle(2.5e-08)
    phase(2.5e-08)
    return (pz, measured())

def correlators(n, k):
    comb = lambda a, b: math.comb(a, b) if 0 <= b <= a else 0
    weights = np.array([x.bit_count() for x in range(2 ** n)])
    table = np.array([[sum(((-1) ** j * comb(w, j) * comb(n - w, order - j) for j in range(order + 1))) / comb(n, order) for order in range(1, n + 1)] for w in weights])
    ideal = np.array([comb(order, order // 2) * comb(n - order, k - order // 2) / comb(n, k) if order % 2 == 0 else 0 for order in range(1, n + 1)])
    return (weights, table, ideal)

def proxy_scores(pz, px, n, k, shots=10000):
    weights, table, ideal = correlators(n, k)
    subspace = pz[:, weights == k]
    fraction = subspace.sum(axis=1)
    conditional = subspace / fraction[:, None]
    zscore = 1 / fraction - np.sum(conditional ** 2, axis=1)
    zscore += shots * np.sum((conditional - 1 / math.comb(n, k)) ** 2, axis=1)
    xscore = np.sum(((px @ table - ideal) / np.where(ideal, ideal, 1)) ** 2, axis=1)
    return 1 / (zscore + xscore)

def mean_scores(pz, px, n, k, shots=10000, order=160):
    weights, table, ideal = correlators(n, k)
    subspace = pz[:, weights == k]
    fraction = subspace.sum(axis=1)
    conditional = subspace / fraction[:, None]
    count = conditional.shape[1]
    zmean = math.sqrt(shots) * (conditional - 1 / count)
    zcov = (np.eye(count)[None] * conditional[:, None, :] - conditional[:, :, None] * conditional[:, None, :]) / fraction[:, None, None]
    zeigen, zvectors = np.linalg.eigh(zcov)
    zprojection = np.einsum('bji,bj->bi', zvectors, zmean)
    xmean = px @ table
    xcov = (np.einsum('bj,ji,jk->bik', px, table, table) - xmean[:, :, None] * xmean[:, None, :]) / shots
    scale = np.where(ideal, ideal, 1)
    xcov /= scale[None, :, None] * scale[None, None, :]
    xeigen, xvectors = np.linalg.eigh(xcov)
    xprojection = np.einsum('bji,bj->bi', xvectors, (xmean - ideal) / scale)
    eigenvalues = np.concatenate((zeigen[:, 1:], xeigen), axis=1)
    means_squared = np.concatenate((zprojection[:, 1:] ** 2, xprojection ** 2), axis=1)
    nodes, quadrature = np.polynomial.legendre.leggauss(order)
    nodes, quadrature = ((nodes + 1) / 2, quadrature / 2)
    a = 1 / (count * fraction)
    t = (1 - nodes)[None, :] / (2 * a[:, None] * nodes[None, :])
    factors = 1 + 2 * t[:, :, None] * np.maximum(eigenvalues[:, None, :], 0)
    logs = -0.5 * np.log(factors).sum(axis=2)
    logs -= np.sum(t[:, :, None] * means_squared[:, None, :] / factors, axis=2)
    return np.exp(logs) / (2 * a[:, None] * nodes[None, :] ** 2) @ quadrature

def circuit_score(circuit, qubits, calibration, k):
    logical = sorted(qubits)
    pz, px = batch_probabilities_detuned(circuit, logical, [logical], calibration)
    score = mean_scores if len(logical) <= 4 else proxy_scores
    return float(score(pz, px, len(logical), k)[0])

def enumerate_embeddings(n, edges, calibration):
    cz, sq, zero, one = calibration
    active = set(sq) & set(zero) & set(one)
    adjacency = {q: set() for q in active}
    for edge in cz:
        a, b = tuple(edge)
        if a in active and b in active and (a != b):
            adjacency[a].add(b)
            adjacency[b].add(a)
    neighbours = {q: set() for q in range(n)}
    for a, b in edges:
        neighbours[a].add(b)
        neighbours[b].add(a)
    results, mapping = ([], {})

    def visit():
        if len(mapping) == n:
            results.append(tuple((mapping[q] for q in range(n))))
            return
        q = max((q for q in range(n) if q not in mapping), key=lambda q: (len(neighbours[q] & mapping.keys()), len(neighbours[q])))
        assigned = neighbours[q] & mapping.keys()
        candidates = set.intersection(*(adjacency[mapping[p]] for p in assigned)) if assigned else active
        for physical in sorted(candidates - set(mapping.values())):
            mapping[q] = physical
            visit()
            del mapping[q]
    visit()
    return results

def choose_small(templates, calibration, n, k):
    best = None
    for circuit, logical in templates:
        index = {q: i for i, q in enumerate(logical)}
        edges = {(min(index[op.qubits[0]], index[op.qubits[1]]), max(index[op.qubits[0]], index[op.qubits[1]])) for op in circuit.all_operations() if op.gate == cirq.CZ}
        placements = enumerate_embeddings(n, edges, calibration)
        if not placements:
            continue
        pz, px = batch_probabilities(circuit, logical, placements, calibration)
        scores = mean_scores(pz, px, n, k)
        chosen = int(np.argmax(scores))
        if best is None or scores[chosen] > best[0]:
            mapping = dict(zip(logical, placements[chosen]))
            best = (float(scores[chosen]), circuit.transform_qubits(mapping), set(mapping.values()))
    if best is None:
        raise NotImplementedError('no calibrated small-state placement')
    return (best[1], best[2])

def flagged_step(n_qubits, k, m, l_min=None):
    r_min = max(0, (k if l_min is None else l_min) - (n_qubits - m))
    r_max = min(k, m)
    first = {m - 1 - r: r for r in range(max(1, r_min), min(r_max, m - 1) + 1)}
    if not first:
        return []
    h_min = min(first)
    return [("flagged" if p > h_min else "givens", p, precomputed_rotations[m][first[p]])
            if p in first else ("givens", p, math.pi / 2) for p in range(h_min, m - 1)]


def analytic_structure(k):
    sequence = [(0, 1), (1, 2), (0, 1), (1, 2)]
    for p in range(2, k):
        sequence += [(p, p + 1), (p, p + 1), (p - 1, p), (p, p + 1), (p, p + 1)]
    return sequence


def analytic_ops(qubits, m, k):
    high, low = precomputed_rotations[m][k], precomputed_rotations[m][k - 1]
    theta = (-high, 0, -math.pi / 2, high, math.pi / 2,
             math.pi / 2 + low, low, 0, -math.pi / 2, -math.pi / 2, math.pi / 2)
    ops = [cirq.ry(theta[j]).on(q) for j, q in enumerate(qubits[:3])]
    for j, (a, b) in enumerate(((0, 1), (1, 2), (0, 1), (1, 2))):
        ops += [cirq.CZ(qubits[a], qubits[b]), cirq.ry(theta[3 + 2 * j]).on(qubits[a]),
                cirq.ry(theta[4 + 2 * j]).on(qubits[b])]
    for p in range(2, k):
        ops += flagged_givens(qubits[p - 1], qubits[p], qubits[p + 1], precomputed_rotations[m][k - p])
    return ops


def line_plan(n_qubits, k, use_blocks=True, l_min=None):
    steps, weights = [], [0] * max(n_qubits - 1, 0)
    for m in range(n_qubits, 1, -1):
        gates = flagged_step(n_qubits, k, m, l_min)
        flagged_cost = sum(5 if gate[0] == "flagged" else 2 for gate in gates)
        r_min = max(0, (k if l_min is None else l_min) - (n_qubits - m))
        r_max = min(k, m)
        j = k - r_min if r_max == k and 0 < r_min <= k else None
        start = start_blocks.get((k, j)) if j is not None else None
        candidates = []
        if gates:
            candidates.append((flagged_cost, ("flagged", m, gates)))
        if use_blocks and m > k >= 2:
            kind = "block" if (m, k) in block_angles else "analytic"
            candidates.append((5 * k - 6, (kind, m, m - k - 1)))
        if start is not None and m in start["angles"]:
            candidates.append((len(start["seq"]), ("start", m, m - k - 1, (k, j))))
        if not candidates:
            continue
        _, step = min(candidates, key=lambda item: item[0])
        steps.append(step)
        if step[0] == "flagged":
            for kind, p, _ in step[2]:
                weights[p] += 2 if kind == "givens" else 4
                if kind == "flagged":
                    weights[p - 1] += 1
        else:
            if step[0] == "start":
                sequence = start_blocks[step[3]]["seq"]
            else:
                sequence = block_structure(k) if step[0] == "block" else analytic_structure(k)
            for a, b in sequence:
                weights[step[2] + min(a, b)] += 1
    return steps, weights


_original_line_ops = line_ops


def line_ops(path, k, steps, preload=True):
    if not any(step[0] == "analytic" for step in steps):
        return _original_line_ops(path, k, steps, preload)
    ops = [cirq.X(q) for q in path[len(path) - k:]] if preload else []
    for step in steps:
        if step[0] == "analytic":
            _, m, offset = step
            ops += analytic_ops(path[offset: offset + k + 1], m, k)
        else:
            ops += _original_line_ops(path, k, [step], False)
    return ops


def split_ops(left, right, k):
    a, b = len(left), len(right)
    angles = precomputed_splits[a, b, k]
    top, bottom = left[a - k:], right[b - k:]
    ops = [cirq.ry(angles[0]).on(top[k - 1])]
    for j in range(1, k):
        theta = angles[j]
        ops += [cirq.ry(-theta / 2).on(top[k - 1 - j]),
                cirq.CZ(top[k - j], top[k - 1 - j]),
                cirq.ry(theta / 2).on(top[k - 1 - j])]
    for j in range(k):
        ops += [cirq.H(bottom[j]), cirq.CZ(top[k - 1 - j], bottom[j]),
                cirq.H(bottom[j]), cirq.X(bottom[j])]
    return ops


