precomputed_w_rotations = ((0.0,),) + tuple(tuple(2 * math.asin(math.sqrt(s / n)) for s in range(n + 1)) for n in range(1, 106))

class _SplitAngles(dict):
    #ry angles of split_ops: the unary chain's conditional tail probabilities of l ~ hypergeometric(a, b, k)
    def __missing__(self, key):
        a, b, k = key
        p = [math.comb(a, l) * math.comb(b, k - l) / math.comb(a + b, k) for l in range(k + 1)]
        tail = [sum(p[j:]) for j in range(k + 2)]
        angles = (2 * math.asin(math.sqrt(min(1.0, tail[1]))),) + tuple(
            2 * math.asin(math.sqrt(min(1.0, tail[j + 1] / tail[j]))) if tail[j] > 0 else 0.0 for j in range(1, k))
        self[key] = angles
        return angles


