import types

import cirq
import numpy as np

def _frame_apply_one(state, q, matrix):
    return np.moveaxis(np.tensordot(matrix, state, axes=([1], [q])), 0, q)

def _frame_native(circuit, qubits, policy='population', seed=0):
    labels = sorted(qubits)
    index = {q: j for j, q in enumerate(labels)}
    n = len(labels)
    last = {q: max((j for j, moment in enumerate(circuit) if any((op.qubits == (q,) for op in moment))), default=-1) for q in labels}
    blocked = {(j, q) for q, j in last.items()}
    recent = {q: None for q in labels}
    for j, moment in enumerate(circuit):
        for op in moment:
            if len(op.qubits) == 1:
                recent[op.qubits[0]] = (j, op.qubits[0])
            else:
                assert op.gate == cirq.CZ
                a, b = op.qubits
                if j > last[a] and recent[b] is not None:
                    blocked.add(recent[b])
                if j > last[b] and recent[a] is not None:
                    blocked.add(recent[a])
    identity = np.eye(2, dtype=np.complex128)
    paulis = {(x, z): (cirq.unitary(cirq.X) if x else identity) @ (cirq.unitary(cirq.Z) if z else identity) for x in (0, 1) for z in (0, 1)}
    state = np.zeros((2,) * n, dtype=np.complex128)
    state[(0,) * n] = 1
    x, z = (np.zeros(n, dtype=int), np.zeros(n, dtype=int))
    visits = np.zeros(n, dtype=int)
    rng = np.random.default_rng(seed)
    original_exposure, dressed_exposure, changes = (0.0, 0.0, 0)
    moments = []
    for j, moment in enumerate(circuit):
        operations = []
        for op in moment:
            if op.gate == cirq.CZ:
                a, b = [index[q] for q in op.qubits]
                position = [slice(None)] * n
                position[a] = position[b] = 1
                state[tuple(position)] *= -1
                z[a] ^= x[b]
                z[b] ^= x[a]
                operations.append(op)
                continue
            assert len(op.qubits) == 1
            q = op.qubits[0]
            a = index[q]
            matrix = cirq.unitary(op)
            state = _frame_apply_one(state, a, matrix)
            population = float(np.sum(np.abs(np.take(state, 1, axis=a)) ** 2))
            proposed = 0
            if policy == 'population':
                proposed = int(population > 0.5 + 1e-10)
            elif policy == 'hybrid':
                proposed = int(population > 0.5) if abs(population - 0.5) > 1e-08 else (visits[a] + a) % 2
            elif policy == 'echo':
                proposed = (visits[a] + a) % 2
            elif policy == 'random':
                proposed = int(rng.integers(2))
            elif policy != 'identity':
                raise ValueError(policy)
            if (j, q) in blocked:
                proposed = 0
            dressed = paulis[proposed, 0] @ matrix @ paulis[x[a], z[a]].conj().T
            operations.append(cirq.PhasedXZGate.from_matrix(dressed).on(q))
            changes += int(proposed != x[a] or z[a] != 0)
            x[a], z[a] = (proposed, 0)
            visits[a] += 1
        duration = 4.2e-08 if any((len(op.qubits) == 2 for op in moment)) else 2.5e-08
        populations = np.array([np.sum(np.abs(np.take(state, 1, axis=a)) ** 2) for a in range(n)])
        original_exposure += duration * populations.sum()
        dressed_exposure += duration * np.where(x, 1 - populations, populations).sum()
        moments.append(cirq.Moment(operations))
    assert not x.any() and (not z.any()), (x, z)
    result = cirq.Circuit(moments)
    assert len(result) == len(circuit)
    assert [len(moment) for moment in result] == [len(moment) for moment in circuit]
    return (result, dict(changes=changes, original_exposure=float(original_exposure), dressed_exposure=float(dressed_exposure), allowed=int(sum(visits) - len(blocked))))


_frame_previous_create = create_dicke_state


def create_dicke_state(num_qubits, num_excitations, cz_pauli_error_rate,
                       sq_pauli_error_rate, zero_errors, one_errors,
                       dynamical_decoupling=True, pack=False, use_blocks=True):
    circuit, qs = _frame_previous_create(num_qubits, num_excitations, cz_pauli_error_rate,
                                         sq_pauli_error_rate, zero_errors, one_errors,
                                         dynamical_decoupling, pack, use_blocks)
    if (int(num_qubits), int(num_excitations)) == (8, 4) and dynamical_decoupling and not pack:
        circuit, _ = _frame_native(circuit, qs, "population")
    return circuit, qs


_w_baseline = types.SimpleNamespace(**globals())
_w_previous_create = create_dicke_state


_w_T1 = 68e-6
_w_T2 = 89e-6
_w_DUR_CZ = 42e-9
_w_DUR_1Q = 25e-9

import itertools
import cirq
import numpy as np
_w_I = np.eye(2, dtype=complex)
_w_X = np.array([[0, 1], [1, 0]], dtype=complex)
_w_Y = np.array([[0, -1j], [1j, 0]], dtype=complex)
_w_Z = np.diag([1.0, -1.0]).astype(complex)
_w_LOWER = np.array([[0, 1], [0, 0]], dtype=complex)
_w_NUMBER = np.diag([0.0, 1.0]).astype(complex)

def _w_apply_local(state, matrix, axis):
    return np.moveaxis(np.tensordot(matrix, state, axes=([1], [axis])), 0, axis)

def _w_apply_gate(state, op, index, batch=False, inverse=False):
    offset = int(batch)
    if op.gate == cirq.CZ:
        state = state.copy()
        sl = [slice(None)] * state.ndim
        for q in op.qubits:
            sl[index[q] + offset] = 1
        state[tuple(sl)] *= -1
        return state
    assert len(op.qubits) == 1
    matrix = cirq.unitary(op)
    return _w_apply_local(state, matrix.conj().T if inverse else matrix, index[op.qubits[0]] + offset)

def _w_probabilities(circuit, cal):
    qs = sorted(circuit.all_qubits())
    n = len(qs)
    if not 2 <= n <= 12:
        raise ValueError('Sensitivity prototype supports 2<=N<=12')
    index = {q: i for i, q in enumerate(qs)}
    edges = {frozenset(q): rate(v) for q, v in cal[0].items()}
    state = np.zeros((2,) * n, dtype=complex)
    state[(0,) * n] = 1
    forward = []
    for moment in circuit:
        for op in moment:
            state = _w_apply_gate(state, op, index)
        forward.append(state.copy())
    valid = np.array([1 << n - i - 1 for i in range(n)])
    amplitudes = state.reshape(-1)[valid]
    ideal = abs(amplitudes) ** 2
    if not np.allclose(ideal, 1 / n, atol=1e-10, rtol=0) or max(abs(amplitudes - amplitudes[0])) > 1e-10:
        raise ValueError('Input must prepare an exact W state')
    backward = np.zeros((n, 2 ** n), dtype=complex)
    backward[np.arange(n), valid] = 1
    backward = backward.reshape((n,) + (2,) * n)
    terms = {key: np.zeros(n) for key in ('single_qubit', 'two_qubit', 'relaxation', 'dephasing', 'readout')}
    tphi = 1 / (1 / _w_T2 - 1 / (2 * _w_T1))
    for t in range(len(circuit) - 1, -1, -1):
        moment = circuit[t]
        state = forward[t]
        bras = backward.reshape(n, -1).conj()
        project = lambda vector: bras @ vector.reshape(-1)
        amp = project(state)
        p = abs(amp) ** 2
        duration = _w_DUR_CZ if any((len(op.qubits) == 2 for op in moment)) else _w_DUR_1Q
        for op in moment:
            positions = [index[q] for q in op.qubits]
            delta = np.zeros(n)
            for labels in itertools.product(range(4), repeat=len(positions)):
                if not any(labels):
                    continue
                perturbed = state
                for axis, label in zip(positions, labels):
                    if label:
                        perturbed = _w_apply_local(perturbed, (_w_I, _w_X, _w_Y, _w_Z)[label], axis)
                delta += abs(project(perturbed)) ** 2 - p
            error_rate = rate(cal[1][op.qubits[0]]) if len(positions) == 1 else edges[frozenset(op.qubits)]
            terms['single_qubit' if len(positions) == 1 else 'two_qubit'] += error_rate / (4 ** len(positions) - 1) * delta
        for axis in range(n):
            occupied = project(_w_apply_local(state, _w_NUMBER, axis))
            anti = np.real(amp.conj() * occupied)
            lowered = project(_w_apply_local(state, _w_LOWER, axis))
            terms['relaxation'] += duration / _w_T1 * (abs(lowered) ** 2 - anti)
            terms['dephasing'] += 2 * duration / tphi * (abs(occupied) ** 2 - anti)
        for op in reversed(tuple(moment.operations)):
            backward = _w_apply_gate(backward, op, index, batch=True, inverse=True)
    zeros = np.array([rate(cal[2][q]) for q in qs])
    ones = np.array([rate(cal[3][q]) for q in qs])
    terms['readout'] = -(ones + zeros.sum() - zeros) / n
    return (ideal + sum(terms.values()), terms)

import collections
import time
import numpy as np

def _w_select(n, cal, shortlist=16):
    tick = time.monotonic()
    reference, reference_qs = _w_baseline.create_dicke_state(n, 1, *cal)
    if not 2 <= n <= 12:
        return (reference, reference_qs, reference, reference_qs, {'fallback': 'outside pilot domain'})
    adj, node = _w_baseline.make_chip(*cal, n, 1)
    skew = {q: rate(cal[3][q]) - rate(cal[2][q]) for q in node}
    bias = lambda qs: _w_baseline.readout_bias(qs, n, 1, skew)
    trees = {}
    for root in sorted(node, key=lambda q: (node[q], q)):
        if time.monotonic() - tick > 8:
            break
        for name, builder in [('prim', _w_baseline.prim_tree), ('bfs', _w_baseline.bfs_tree), ('bias', lambda a, nd, r, m: _w_baseline.bias_tree(a, nd, r, m, bias))]:
            parent = builder(adj, node, root, n)
            if parent is None:
                continue
            children = collections.defaultdict(list)
            for c, p in parent.items():
                children[p].append(c)
            children, rounds, _ = _w_baseline.broadcast_order(root, children)
            qs = {root, *parent}
            heuristic = sum((node[q] for q in qs)) + sum((2 * adj[c][p] for c, p in parent.items())) + _w_baseline.idle_penalty * rounds * n / 2 + bias(qs)
            key = (root, tuple(sorted(parent.items())))
            trees[key] = (heuristic, name, root, children, qs)

    def cost(circuit, qs):
        valid, terms = _w_probabilities(circuit, cal)
        fraction = float(valid.sum())
        if min(valid) <= 0 or not 0 < fraction <= 1 + 1e-10:
            return dict(cost=float('inf'), invalid_expansion=True, moments=len(circuit))
        conditional = valid / fraction
        floor = 1 / fraction - float(sum(conditional ** 2))
        bias_cost = _w_baseline.shots * float(sum((conditional - 1 / n) ** 2))
        return dict(cost=floor + bias_cost, Z_floor=floor, Z_bias=bias_cost, valid_fraction=fraction, valid_probabilities=valid.tolist(), terms={k: v.tolist() for k, v in terms.items()}, moments=len(circuit))
    best_c, best_qs = (reference, reference_qs)
    first = dict(name='baseline', **cost(reference, reference_qs))
    pool = [first]
    best = first
    circuits = {reference.freeze()}
    for _, name, root, children, qs in sorted(trees.values(), key=lambda x: x[0])[:shortlist]:
        if time.monotonic() - tick > 25:
            break
        circuit = _w_baseline.compile_circuit(_w_baseline.w_ops(root, children), dynamical_decoupling=True, pack=False)
        if circuit.freeze() in circuits:
            continue
        circuits.add(circuit.freeze())
        row = dict(name=name, root=str(root), qubits=[str(q) for q in sorted(qs)], **cost(circuit, qs))
        pool.append(row)
        if row['cost'] < best['cost'] - 1e-08:
            best_c, best_qs, best = (circuit, qs, row)
    return (reference, reference_qs, best_c, best_qs, dict(seconds=time.monotonic() - tick, enumerated=len(trees), pool=pool, selected=best))


def create_dicke_state(num_qubits, num_excitations, cz_pauli_error_rate,
                       sq_pauli_error_rate, zero_errors, one_errors,
                       dynamical_decoupling=True, pack=False, use_blocks=True):
    n, k = int(num_qubits), int(num_excitations)
    if 5 <= n <= 8 and k == 1 and dynamical_decoupling and not pack and use_blocks:
        calibration = (cz_pauli_error_rate, sq_pauli_error_rate, zero_errors, one_errors)
        _, _, circuit, qs, _ = _w_select(n, calibration)
        check_circuit(circuit, cz_pauli_error_rate, sq_pauli_error_rate)
        return circuit, set(qs)
    return _w_previous_create(num_qubits, num_excitations, cz_pauli_error_rate,
                               sq_pauli_error_rate, zero_errors, one_errors,
                               dynamical_decoupling, pack, use_blocks)


_response_baseline = types.SimpleNamespace(**globals())
_response_previous_create = create_dicke_state

def _response_cost(table, errors):
    e = np.asarray(errors)
    f = 1 + e @ np.asarray(table['a'])
    z = 1 / f - 1 / math.comb(table['n'], table['k'])
    z += (table['shots'] - 1) * np.einsum('...i,ij,...j->...', e, table['gram'], e) / f ** 2
    x = table['xbase'] + e @ table['xlinear'] + np.einsum('...i,ij,...j->...', e, table['xgram'], e)
    return np.where(f > 0, z + x, np.inf)

def _response_decode(table, labels):
    moments = []
    for layer in table['layers']:
        ops = []
        for op in layer:
            if op[0] == 'c':
                ops.append(cirq.CZ(labels[op[1]], labels[op[2]]))
            else:
                ops.append(cirq.PhasedXZGate(x_exponent=op[2], z_exponent=op[3], axis_phase_exponent=op[4]).on(labels[op[1]]))
        moments.append(cirq.Moment(ops))
    return cirq.Circuit(moments)

import time
import cirq
import numpy as np
_response_embedding_cache = {}

def _response_select(base, table, calibration, shortlist=2):
    started = time.monotonic()
    n, k = (table['n'], table['k'])
    reference, reference_qs = base.create_dicke_state(n, k, *calibration)
    active = tuple(sorted(set(calibration[1]) & set(calibration[2]) & set(calibration[3])))
    hardware_edges = tuple(sorted({tuple(sorted(edge)) for edge in calibration[0]}))
    template_edges = tuple((tuple(feature[1:]) for feature in table['features'] if feature[0] == 'cz'))
    key = (n, template_edges, active, hardware_edges)
    if key not in _response_embedding_cache:
        if len(_response_embedding_cache) >= 4:
            del _response_embedding_cache[next(iter(_response_embedding_cache))]
        _response_embedding_cache[key] = base.enumerate_embeddings(n, template_edges, calibration)
    embeddings = _response_embedding_cache[key]
    if not embeddings:
        return (reference, reference_qs, reference, reference_qs, dict(fallback=True))
    physical = {q: i for i, q in enumerate(active)}
    indices = np.array([[physical[q] for q in labels] for labels in embeddings], dtype=np.int16)
    single = np.array([base.rate(calibration[1][q]) for q in active])
    zero = np.array([base.rate(calibration[2][q]) for q in active])
    one = np.array([base.rate(calibration[3][q]) for q in active])
    coupling = np.full((len(active), len(active)), np.inf)
    for (a, b), value in calibration[0].items():
        if a in physical and b in physical:
            coupling[physical[a], physical[b]] = coupling[physical[b], physical[a]] = base.rate(value)
    errors = []
    for feature in table['features']:
        kind, *wires = feature
        if kind == 'thermal':
            errors.append(np.ones(len(embeddings)))
        elif kind == 'cz':
            errors.append(coupling[indices[:, wires[0]], indices[:, wires[1]]])
        else:
            source = {'sq': single, 'zero': zero, 'one': one}[kind]
            errors.append(source[indices[:, wires[0]]])
    errors = np.stack(errors, axis=1)
    costs = _response_cost(table, errors)
    chosen = np.argsort(costs)[:shortlist]
    placements = [embeddings[j] for j in chosen]
    logical = cirq.LineQubit.range(n)
    template = _response_decode(table, logical)
    pz, px = base.batch_probabilities_detuned(template, logical, placements, calibration)
    scores = base.proxy_scores(pz, px, n, k)
    baseline_score = base.circuit_score(reference, reference_qs, calibration, k)
    best = int(np.argmax(scores))
    if scores[best] > baseline_score + 1e-08:
        selected = template.transform_qubits(dict(zip(logical, placements[best])))
        selected_qs = set(placements[best])
    else:
        selected, selected_qs = (reference, reference_qs)
    return (reference, reference_qs, selected, selected_qs, dict(embeddings=len(embeddings), surrogate_costs=costs[chosen].tolist(), density_scores=scores.tolist(), baseline_density=float(baseline_score), changed=selected != reference, seconds=time.monotonic() - started))

