def create_dicke_state_adaptive(num_qubits, num_excitations):
    entry = _BONUS_TABLE.get(f"{int(num_qubits)},{int(num_excitations)}")
    if entry is None:
        raise NotImplementedError(f"no bonus circuit for ({num_qubits}, {num_excitations})")
    qubits, moments = entry
    g = cirq.GridQubit
    circuit = cirq.Circuit(cirq.Moment(
        cirq.CZ(g(o[0], o[1]), g(o[2], o[3])) if len(o) == 4 else
        cirq.PhasedXZGate(x_exponent=o[2], z_exponent=o[3], axis_phase_exponent=o[4]).on(g(o[0], o[1]))
        for o in m) for m in moments)
    return circuit, {g(r, c) for r, c in qubits}
